                    console.log(`   Customer: ${event.data.object.customer_email}`);
                    console.log(`   Amount: $${(event.data.object.amount_due / 100).toFixed(2)}`);
                    console.log(`   Response: ${data}\n`);
                    resolve(data);
                });
            });

            req.on('error', (err) => {
                console.error(`❌ Error sending ${event.type}:`, err.message);
                reject(err);
            });

            req.write(postData);
            req.end();
        }, delay);
    });
}

/**
